ALTER TABLE public.orders ADD COLUMN payment_method text NOT NULL DEFAULT 'ONLINE' CHECK(payment_method IN ('ONLINE','COD')), ADD COLUMN cod_collected_at timestamptz, ADD COLUMN cod_collection_reference text;
CREATE TABLE public.product_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id text NOT NULL REFERENCES public.products(id), object_path text NOT NULL UNIQUE, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.product_images TO authenticated; GRANT SELECT ON public.product_images TO anon; GRANT ALL ON public.product_images TO service_role;
ALTER TABLE public.product_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY visible_product_images ON public.product_images FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.products WHERE id=product_id AND status='active'));
CREATE POLICY staff_product_images ON public.product_images FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','catalogue'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','catalogue']));
CREATE POLICY staff_photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='product-images' AND public.staff_has_role(ARRAY['owner','admin','catalogue']) AND name ~ '^[a-z0-9-]+/[a-f0-9-]+\.(jpg|png|webp)$');
CREATE POLICY staff_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='product-images' AND public.staff_has_role(ARRAY['owner','admin','catalogue']));
CREATE POLICY staff_photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='product-images' AND public.staff_has_role(ARRAY['owner','admin','catalogue']));
CREATE POLICY catalogue_photo_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='product-images' AND EXISTS(SELECT 1 FROM public.product_images pi JOIN public.products p ON p.id=pi.product_id WHERE pi.object_path=name AND p.status='active'));
CREATE TABLE public.supplier_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fulfillment_id uuid UNIQUE NOT NULL REFERENCES public.fulfillments(id), supplier_id uuid NOT NULL REFERENCES public.suppliers(id), status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','acknowledged','failed','completed','cancelled')), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.supplier_tasks TO authenticated; GRANT ALL ON public.supplier_tasks TO service_role;
ALTER TABLE public.supplier_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY operations_supplier_tasks ON public.supplier_tasks FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations']));
CREATE TABLE public.refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), request_id uuid UNIQUE NOT NULL REFERENCES public.order_requests(id), amount_paise integer NOT NULL CHECK(amount_paise>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')), transfer_reference text UNIQUE, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.refunds TO authenticated; GRANT ALL ON public.refunds TO service_role;
ALTER TABLE public.refunds ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_refunds ON public.refunds FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders WHERE id=order_id AND user_id=auth.uid()));
CREATE POLICY staff_refunds ON public.refunds FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','support']));
CREATE OR REPLACE FUNCTION public.quote_cod_order(_items jsonb,_pincode text,_coupon text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE i jsonb; p public.products; s public.shipping_rules; c public.coupons; qty integer; sub bigint:=0; disc bigint:=0; tax bigint:=0; reason text:=NULL; result jsonb; BEGIN
IF jsonb_typeof(_items) IS DISTINCT FROM 'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid cart'; END IF;
IF (SELECT count(DISTINCT value->>'productId') FROM jsonb_array_elements(_items))<>jsonb_array_length(_items) THEN RAISE EXCEPTION 'Duplicate cart item'; END IF;
SELECT * INTO s FROM public.shipping_rules WHERE pincode=_pincode AND active;
IF NOT FOUND THEN reason:='Delivery is not configured for this PIN'; END IF;
FOR i IN SELECT value FROM jsonb_array_elements(_items) LOOP
qty:=(i->>'quantity')::integer; IF qty IS NULL OR qty NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid quantity'; END IF;
SELECT * INTO p FROM public.products WHERE id=i->>'productId' AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Product unavailable'; END IF;
sub:=sub+p.price_paise::bigint*qty;
IF p.is_demo THEN reason:='Demonstration products cannot be ordered'; ELSIF p.tax_bps IS NULL THEN reason:='Product tax settings require verification'; END IF;
IF p.fulfillment_model='OWN_INVENTORY' AND NOT EXISTS(SELECT 1 FROM public.inventory WHERE product_id=p.id AND quantity-reserved>=qty) THEN reason:=coalesce(reason,'Insufficient stock'); END IF;
IF p.fulfillment_model='DROPSHIP' AND NOT EXISTS(SELECT 1 FROM public.supplier_products sp JOIN public.suppliers ss ON ss.id=sp.supplier_id WHERE sp.product_id=p.id AND sp.available AND ss.approved AND ss.manual_fulfillment) THEN reason:=coalesce(reason,'Supplier availability is not confirmed'); END IF;
END LOOP;
IF length(trim(_coupon))>0 THEN SELECT * INTO c FROM public.coupons WHERE code=upper(trim(_coupon)) AND active AND starts_at<=now() AND ends_at>now() AND sub>=min_subtotal_paise; IF NOT FOUND THEN RAISE EXCEPTION 'Coupon invalid or expired'; END IF; disc:=least(c.max_discount_paise,round(sub*c.percent/100.0)::bigint); END IF;
FOR i IN SELECT value FROM jsonb_array_elements(_items) LOOP SELECT * INTO p FROM public.products WHERE id=i->>'productId'; IF NOT p.tax_inclusive THEN tax:=tax+round(p.price_paise::numeric*(i->>'quantity')::integer*(1-CASE WHEN sub>0 THEN disc::numeric/sub ELSE 0 END)*coalesce(p.tax_bps,0)/10000)::bigint; END IF; END LOOP;
IF sub+tax+coalesce(s.fee_paise,0)-disc>2147483647 THEN RAISE EXCEPTION 'Order value too large'; END IF;
RETURN jsonb_build_object('subtotal',sub,'discount',disc,'tax',tax,'shipping',s.fee_paise,'payable',CASE WHEN reason IS NULL THEN sub-disc+tax+s.fee_paise ELSE NULL END,'purchasingEnabled',reason IS NULL,'paymentMethod','COD','reason',reason,'minDays',s.min_days,'maxDays',s.max_days);
END $$;
REVOKE ALL ON FUNCTION public.quote_cod_order(jsonb,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.quote_cod_order(jsonb,text,text) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.place_cod_order(_address jsonb,_items jsonb,_coupon text,_key uuid,_expected integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid(); o uuid; a uuid; q jsonb; BEGIN
IF u IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _key IS NULL THEN RAISE EXCEPTION 'Idempotency key required'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(u::text,0)); SELECT id INTO o FROM public.orders WHERE user_id=u AND idempotency_key=_key; IF FOUND THEN RETURN o; END IF;
IF (SELECT count(*) FROM public.orders WHERE user_id=u AND created_at>now()-interval '1 hour')>=10 THEN RAISE EXCEPTION 'Order limit reached; contact support'; END IF;
IF coalesce(_address->>'phone','') !~ '^[6-9][0-9]{9}$' OR coalesce(_address->>'pincode','') !~ '^[1-9][0-9]{5}$' OR length(trim(coalesce(_address->>'name',''))) NOT BETWEEN 2 AND 100 OR length(trim(coalesce(_address->>'line1',''))) NOT BETWEEN 5 AND 250 OR length(trim(coalesce(_address->>'city',''))) NOT BETWEEN 2 AND 100 OR length(trim(coalesce(_address->>'state',''))) NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'Invalid address'; END IF;
PERFORM 1 FROM public.products WHERE id IN(SELECT value->>'productId' FROM jsonb_array_elements(_items)) ORDER BY id FOR UPDATE;
q:=public.quote_cod_order(_items,_address->>'pincode',_coupon); IF NOT (q->>'purchasingEnabled')::boolean THEN RAISE EXCEPTION '%',q->>'reason'; END IF;
IF _expected IS NULL OR _expected<>(q->>'payable')::integer THEN RAISE EXCEPTION 'Prices changed; review the order again'; END IF;
INSERT INTO public.addresses(user_id,name,phone,line1,city,state,pincode) VALUES(u,_address->>'name',_address->>'phone',_address->>'line1',_address->>'city',_address->>'state',_address->>'pincode') RETURNING id INTO a;
o:=public.reserve_customer_order(u,a,_items,_key);
UPDATE public.orders SET status='confirmed',payment_method='COD',payment_status='pending',discount_paise=(q->>'discount')::integer,tax_paise=(q->>'tax')::integer,total_paise=(q->>'payable')::integer,reservation_expires_at=NULL WHERE id=o;
UPDATE public.inventory inv SET quantity=inv.quantity-oi.quantity,reserved=inv.reserved-oi.quantity FROM public.order_items oi WHERE oi.order_id=o AND oi.product_id=inv.product_id AND oi.fulfillment_model='OWN_INVENTORY';
INSERT INTO public.inventory_movements(product_id,delta,reason,actor_id) SELECT product_id,-quantity,'COD order '||o::text,u FROM public.order_items WHERE order_id=o AND fulfillment_model='OWN_INVENTORY';
UPDATE public.fulfillments SET status=CASE WHEN supplier_id IS NULL THEN 'processing' ELSE 'awaiting_supplier_fulfillment' END WHERE order_id=o;
INSERT INTO public.supplier_tasks(fulfillment_id,supplier_id,due_at) SELECT f.id,f.supplier_id,now()+make_interval(days=>coalesce(sp.dispatch_sla_days,0)) FROM public.fulfillments f JOIN public.order_items oi ON oi.id=f.item_id JOIN public.supplier_products sp ON sp.product_id=oi.product_id AND sp.supplier_id=f.supplier_id WHERE f.order_id=o AND f.supplier_id IS NOT NULL;
DELETE FROM public.cart_items WHERE user_id=u AND product_id IN(SELECT product_id FROM public.order_items WHERE order_id=o);
RETURN o; END $$;
REVOKE ALL ON FUNCTION public.place_cod_order(jsonb,jsonb,text,uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.place_cod_order(jsonb,jsonb,text,uuid,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.update_fulfillment(_id uuid,_status text,_carrier text,_tracking text,_url text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.fulfillments; o public.orders; BEGIN
IF NOT public.staff_has_role(ARRAY['owner','admin','operations']) THEN RAISE EXCEPTION 'Forbidden'; END IF;
SELECT * INTO f FROM public.fulfillments WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Shipment unavailable'; END IF;
SELECT * INTO o FROM public.orders WHERE id=f.order_id FOR UPDATE; SELECT * INTO f FROM public.fulfillments WHERE id=_id FOR UPDATE;
IF o.status IN ('cancelled','returned','refunded') OR NOT(o.payment_status='paid' OR o.payment_method='COD') THEN RAISE EXCEPTION 'Order not ready'; END IF;
IF NOT ((f.status IN ('processing','awaiting_supplier_fulfillment') AND _status='shipped') OR (f.status='shipped' AND _status IN ('out_for_delivery','delivered')) OR (f.status='out_for_delivery' AND _status='delivered')) THEN RAISE EXCEPTION 'Invalid fulfillment transition'; END IF;
IF _status='shipped' AND (coalesce(length(trim(_carrier)),0)=0 OR coalesce(length(trim(_tracking)),0)=0 OR (_url<>'' AND _url NOT LIKE 'https://%')) THEN RAISE EXCEPTION 'Carrier and tracking required'; END IF;
UPDATE public.fulfillments SET status=_status,carrier=nullif(_carrier,''),tracking_number=nullif(_tracking,''),tracking_url=nullif(_url,''),updated_at=now() WHERE id=f.id;
IF _status='shipped' THEN UPDATE public.supplier_tasks SET status='completed',updated_at=now() WHERE fulfillment_id=f.id; END IF;
IF NOT EXISTS(SELECT 1 FROM public.fulfillments WHERE order_id=o.id AND status<>'delivered') THEN UPDATE public.orders SET status='delivered',delivered_at=now() WHERE id=o.id; ELSIF NOT EXISTS(SELECT 1 FROM public.fulfillments WHERE order_id=o.id AND status NOT IN ('shipped','out_for_delivery','delivered')) THEN UPDATE public.orders SET status='shipped' WHERE id=o.id; END IF;
INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),'fulfillment:'||_status,f.id::text,jsonb_build_object('order_id',o.id)); END $$;
CREATE OR REPLACE FUNCTION public.collect_cod(_order uuid,_amount integer,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; BEGIN IF NOT public.staff_has_role(ARRAY['owner','admin','operations']) THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO o FROM public.orders WHERE id=_order FOR UPDATE; IF NOT FOUND OR o.payment_method<>'COD' OR o.status<>'delivered' OR _amount IS DISTINCT FROM o.total_paise OR coalesce(length(trim(_reference)),0) NOT BETWEEN 5 AND 150 THEN RAISE EXCEPTION 'Delivered COD order and exact collection reference required'; END IF; IF o.payment_status='paid' THEN IF o.cod_collection_reference=_reference THEN RETURN; ELSE RAISE EXCEPTION 'Collection already recorded'; END IF; END IF; UPDATE public.orders SET payment_status='paid',cod_collected_at=now(),cod_collection_reference=_reference WHERE id=_order; INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),'cod:collected',_order::text,jsonb_build_object('amount',_amount,'reference',_reference)); END $$;
REVOKE ALL ON FUNCTION public.collect_cod(uuid,integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.collect_cod(uuid,integer,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.update_supplier_task(_id uuid,_action text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.supplier_tasks; BEGIN IF NOT public.staff_has_role(ARRAY['owner','admin','operations']) THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO t FROM public.supplier_tasks WHERE id=_id FOR UPDATE; IF NOT FOUND OR t.status IN ('completed','cancelled') THEN RAISE EXCEPTION 'Task unavailable'; END IF; IF _action NOT IN ('acknowledged','failed','retry') OR coalesce(length(trim(_note)),0) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Action and explanation required'; END IF; IF _action='retry' AND t.status<>'failed' THEN RAISE EXCEPTION 'Only failed tasks can retry'; END IF; UPDATE public.supplier_tasks SET status=CASE WHEN _action='retry' THEN 'queued' ELSE _action END,attempts=attempts+CASE WHEN _action='failed' THEN 1 ELSE 0 END,next_attempt_at=CASE WHEN _action='failed' THEN now()+make_interval(mins=>least(1440,power(2,least(attempts+1,10))::integer)) ELSE now() END,last_error=CASE WHEN _action='failed' THEN _note ELSE NULL END,updated_at=now() WHERE id=_id; INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),'supplier-task:'||_action,_id::text,jsonb_build_object('note',_note)); END $$;
REVOKE ALL ON FUNCTION public.update_supplier_task(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.update_supplier_task(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.complete_cod_request(_request uuid,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.order_requests; o public.orders; BEGIN
IF NOT public.staff_has_role(ARRAY['owner','admin','operations']) THEN RAISE EXCEPTION 'Forbidden'; END IF;
SELECT * INTO r FROM public.order_requests WHERE id=_request; IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable'; END IF; SELECT * INTO o FROM public.orders WHERE id=r.order_id FOR UPDATE; SELECT * INTO r FROM public.order_requests WHERE id=_request FOR UPDATE;
IF r.status='completed' THEN RETURN; END IF; IF r.status<>'approved' OR o.payment_method<>'COD' OR coalesce(length(trim(_note)),0) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Approved COD request and evidence required'; END IF;
IF r.kind='cancellation' THEN IF o.status NOT IN ('confirmed','processing','awaiting_supplier_fulfillment') OR EXISTS(SELECT 1 FROM public.fulfillments WHERE order_id=o.id AND status IN ('shipped','out_for_delivery','delivered')) OR o.payment_status='paid' THEN RAISE EXCEPTION 'Cancellation no longer available'; END IF; ELSE IF o.status<>'delivered' THEN RAISE EXCEPTION 'Delivered return required'; END IF; END IF;
IF r.kind='cancellation' THEN UPDATE public.inventory inv SET quantity=inv.quantity+oi.quantity FROM public.order_items oi WHERE oi.order_id=o.id AND oi.product_id=inv.product_id AND oi.fulfillment_model='OWN_INVENTORY'; INSERT INTO public.inventory_movements(product_id,delta,reason,actor_id) SELECT product_id,quantity,'COD cancellation '||o.id::text,auth.uid() FROM public.order_items WHERE order_id=o.id AND fulfillment_model='OWN_INVENTORY'; END IF;
UPDATE public.orders SET status=CASE WHEN r.kind='cancellation' THEN 'cancelled' ELSE 'returned' END WHERE id=o.id; UPDATE public.fulfillments SET status=CASE WHEN r.kind='cancellation' THEN 'cancelled' ELSE 'returned' END,updated_at=now() WHERE order_id=o.id; UPDATE public.supplier_tasks SET status='cancelled',updated_at=now() WHERE fulfillment_id IN(SELECT id FROM public.fulfillments WHERE order_id=o.id);
IF r.kind='return' AND o.payment_status='paid' AND o.total_paise>0 THEN INSERT INTO public.refunds(order_id,request_id,amount_paise) VALUES(o.id,r.id,o.total_paise); END IF;
UPDATE public.order_requests SET status='completed',staff_note=_note WHERE id=r.id; INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),'request:completed',r.id::text,jsonb_build_object('note',_note)); END $$;
REVOKE ALL ON FUNCTION public.complete_cod_request(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.complete_cod_request(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.complete_cod_refund(_id uuid,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.refunds; o public.orders; BEGIN IF NOT public.staff_has_role(ARRAY['owner','admin']) THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO r FROM public.refunds WHERE id=_id FOR UPDATE; IF NOT FOUND OR coalesce(length(trim(_reference)),0) NOT BETWEEN 5 AND 150 THEN RAISE EXCEPTION 'Refund and transfer reference required'; END IF; SELECT * INTO o FROM public.orders WHERE id=r.order_id FOR UPDATE; IF o.payment_method<>'COD' OR o.payment_status<>'paid' THEN RAISE EXCEPTION 'Collected COD funds required'; END IF; IF r.status='completed' THEN IF r.transfer_reference=_reference THEN RETURN; ELSE RAISE EXCEPTION 'Refund already recorded'; END IF; END IF; UPDATE public.refunds SET status='completed',transfer_reference=_reference,completed_at=now() WHERE id=_id; UPDATE public.orders SET status='refunded' WHERE id=r.order_id; INSERT INTO public.audit_logs(actor_id,action,entity_id,details) VALUES(auth.uid(),'refund:recorded',r.id::text,jsonb_build_object('amount',r.amount_paise,'reference',_reference)); END $$;
REVOKE ALL ON FUNCTION public.complete_cod_refund(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.complete_cod_refund(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.prepare_account_deletion() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); BEGIN
IF u IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF public.staff_has_role(ARRAY['owner','admin','operations','support','catalogue']) THEN RAISE EXCEPTION 'Staff must transfer responsibilities before deletion'; END IF;
IF EXISTS(SELECT 1 FROM public.orders WHERE user_id=u AND status NOT IN ('cancelled','delivered','returned','refunded','failed')) OR EXISTS(SELECT 1 FROM public.orders WHERE user_id=u AND payment_method='COD' AND status IN ('delivered','returned') AND payment_status<>'paid') OR EXISTS(SELECT 1 FROM public.refunds r JOIN public.orders o ON o.id=r.order_id WHERE o.user_id=u AND r.status='pending') OR EXISTS(SELECT 1 FROM public.order_requests WHERE user_id=u AND status IN ('requested','approved')) THEN RAISE EXCEPTION 'Resolve active orders, collections and requests before deletion'; END IF;
DELETE FROM public.cart_items WHERE user_id=u; DELETE FROM public.wishlist WHERE user_id=u; DELETE FROM public.addresses WHERE user_id=u; DELETE FROM public.support_tickets WHERE user_id=u; DELETE FROM public.account_deletion_requests WHERE user_id=u; DELETE FROM public.order_requests WHERE user_id=u AND id NOT IN(SELECT request_id FROM public.refunds);
UPDATE public.orders SET user_id=NULL,address_snapshot=jsonb_build_object('deleted',true) WHERE user_id=u;
UPDATE public.profiles SET display_name='',phone=NULL,preferences='{}' WHERE id=u;
END $$;
REVOKE ALL ON FUNCTION public.prepare_account_deletion() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.prepare_account_deletion() TO authenticated;
CREATE INDEX supplier_tasks_status_idx ON public.supplier_tasks(status,next_attempt_at);